// convenience-empty-body-handling: a 2xx response with an empty body for a
// body-returning operation must surface a typed ApiError from the convenience
// method (not a silent nil / zero-valued struct), while WithHTTPInfo reports
// nil Data.
func TestPetApi_EmptyBodyConvenienceReturnsApiError(t *testing.T) {
	t.Parallel()
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(200)
		// Intentionally write no body.
	}))
	defer server.Close()

	api := newPetApiForMock(t, server)

	_, err := api.GetPetById(int64(1), nil)
	if err == nil {
		t.Fatal("expected a typed ApiError when the body-returning operation receives an empty body")
	}
	var apiErr *pkgerrors.ApiError
	if !errors.As(err, &apiErr) {
		t.Fatalf("expected *ApiError, got %T: %v", err, err)
	}

	result, infoErr := api.GetPetByIdWithHTTPInfo(int64(1), nil)
	if infoErr != nil {
		t.Fatalf("WithHTTPInfo unexpected error: %v", infoErr)
	}
	if result.Data != nil {
		t.Errorf("expected nil Data on empty body, got %v", result.Data)
	}
}

// per-call-auth-override: an Authenticator passed to the BASE operation method
// (not just WithHTTPInfo) must be applied to the outgoing request. The default
// header carries one token; the per-call authenticator carries a different one
// and must win on the wire.
func TestPetApi_AddPetPerCallAuthOverride(t *testing.T) {
	t.Parallel()
	var capturedAuth string
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		capturedAuth = r.Header.Get("Authorization")
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(200)
		_, _ = w.Write([]byte(`{"id":1,"name":"x","photoUrls":[]}`))
	}))
	defer server.Close()

	config := petstore.NewConfigurationBuilder().
		BaseURL(server.URL).
		DefaultHeader("Authorization", "Bearer default-token").
		Build()
	client := petstore.NewDefaultApiClient(nil)
	api := petstore.NewPetApi(client, config, nil)

	perCallAuth := &perCallPetAuth{}
	pet := models.NewPet("OverrideDog", models.Set[string]{"http://example.com/p.jpg"})

	_, err := api.AddPet(*pet, &options.AddPetOptions{Auth: perCallAuth})
	if err != nil {
		t.Fatalf("AddPet failed: %v", err)
	}
	if capturedAuth != "Bearer per-call-token" {
		t.Errorf("expected per-call auth header, got %q", capturedAuth)
	}
}

// enum-reject-unknown-value: deserialising a model whose enum-typed field
// carries a value outside the declared members must fail with a
// (de)serialisation error rather than silently accepting it. Pet.Status is the
// typed PetStatusEnum; a server response with status "banana" must surface an
// error from GetPetById.
func TestPetApi_DeserializeUnknownEnumValueErrors(t *testing.T) {
	t.Parallel()
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(200)
		_, _ = w.Write([]byte(`{"id":1,"name":"x","photoUrls":[],"status":"banana"}`))
	}))
	defer server.Close()

	api := newPetApiForMock(t, server)

	_, err := api.GetPetById(int64(1), nil)
	if err == nil {
		t.Fatal("expected a deserialization error for an unknown enum value, got nil")
	}
	if !strings.Contains(err.Error(), "banana") {
		t.Errorf("expected error to reference the rejected enum value %q, got: %v", "banana", err)
	}
}

